import styled, {createGlobalStyle} from "styled-components";

const GlobalCss = createGlobalStyle`
    *{
        margin: 0;
        padding: 0;
        box-sizing: border-box;
        font-family: Roboto;
        list-style: none;
    }
`

export default GlobalCss
